const Database = require('better-sqlite3');
const db = new Database('/workspace/world.db');

// Get product info
const product = db.prepare(\"SELECT * FROM products WHERE product_id = 'PROD-2028EE'\").get();
console.log('Product:', JSON.stringify(product, null, 2));

// Check schema for rt_variants
const schema = db.prepare(\"SELECT sql FROM sqlite_master WHERE name = 'rt_variants'\").get();
console.log('\nrt_variants schema:', schema.sql);

// Check variants for this product
const variants = db.prepare(\"SELECT * FROM rt_variants WHERE product_id = 'PROD-2028EE'\").all();
console.log('\nVariants:', JSON.stringify(variants, null, 2));
"

node -e "
const Database = require('better-sqlite3');
const db = new Database('/workspace/world.db');

// Check if any other products reference PROD-2028EE in their compatible_with_json
const compatRefs = db.prepare(\"SELECT product_id, name, compatible_with_json FROM products WHERE compatible_with_json LIKE '%PROD-2028EE%'\").all();
console.log('Products that list PROD-2028EE as compatible:', JSON.stringify(compatRefs, null, 2));

// Also check products in the same subcategory for context
const related = db.prepare(\"SELECT product_id, name, compatible_with_json FROM products WHERE subcategory = 'Mobile Accessories'\").all();
console.log('\nAll Mobile Accessories products:');
related.forEach(p => console.log('  ', p.product_id, '-', p.name, '| compatible_with:', p.compatible_with_json));
"

node -e "
const Database = require('better-sqlite3');
const db = new Database('/workspace/world.db');

// Full product record
const product = db.prepare(\"SELECT * FROM products WHERE product_id = 'PROD-2028EE'\").get();
console.log('=== FULL PRODUCT RECORD ===');
console.log(JSON.stringify(product, null, 2));

// Check for any orders containing this product
const orderItems = db.prepare(\"SELECT * FROM order_items WHERE product_id = 'PROD-2028EE'\").all();
console.log('\n=== ORDER ITEMS ===');
console.log(JSON.stringify(orderItems, null, 2));

// Check warranties
const warranties = db.prepare(\"SELECT * FROM warranties WHERE product_id = 'PROD-2028EE'\").all();
console.log('\n=== WARRANTIES ===');
console.log(JSON.stringify(warranties, null, 2));

// Check cart items
const cartItems = db.prepare(\"SELECT * FROM cart_items WHERE product_id = 'PROD-2028EE'\").all();
console.log('\n=== CART ITEMS ===');
console.log(JSON.stringify(cartItems, null, 2));

// Check promotions that might apply
const promos = db.prepare(\"SELECT * FROM promotions WHERE product_id = 'PROD-2028EE' OR category = 'electronics'\").all();
console.log('\n=== PROMOTIONS ===');
console.log(JSON.stringify(promos, null, 2));
"

